# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">OKULDA STATÜ VE MESLEK İFADELERİ (MÜZEKKER - MÜENNES)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">MÜZEKKER (ERİL) İSİMLER</text>\n  <text x="45" y="98" font-size="12" font-weight="bold" fill="#1e3a8a">• طَالِبٌ (Tâlibun) → Erkek öğrenci</text>\n  <text x="45" y="128" font-size="12" font-weight="bold" fill="#1e3a8a">• مُدَرِّسٌ (Muderrisun) → Erkek öğretmen</text>\n  <text x="45" y="158" font-size="12" font-weight="bold" fill="#1e3a8a">• مُدِيرٌ (Mudîrun) → Erkek müdür</text>\n  <text x="45" y="188" font-size="12" font-weight="bold" fill="#1e3a8a">• صَدِيقٌ (Sadîkun) → Erkek arkadaş</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" fill="#1d4ed8">İşaret ve Zamir: هٰذَا (Bu) / هُوَ (O)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fdf2f8" stroke="#db2777" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9d174d">MÜENNES (DİŞİL) İSİMLER (+ ة)</text>\n  <text x="380" y="98" font-size="12" font-weight="bold" fill="#831843">• طَالِبَةٌ (Tâlibetun) → Kız öğrenci</text>\n  <text x="380" y="128" font-size="12" font-weight="bold" fill="#831843">• مُدَرِّسَةٌ (Muderrisetun) → Kadın öğretmen</text>\n  <text x="380" y="158" font-size="12" font-weight="bold" fill="#831843">• مُدِيرَةٌ (Mudîretun) → Kadın müdür</text>\n  <text x="380" y="188" font-size="12" font-weight="bold" fill="#831843">• صَدِيقَةٌ (Sadîkatun) → Kız arkadaş</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" fill="#be185d">İşaret ve Zamir: هٰذِهِ (Bu) / هِيَ (O)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KİM SORUSU (مَنْ؟) VE İYELİK ZAMİRLERİYLE İSİM SORMA</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">مَنْ هٰذَا / مَنْ هٰذِهِ؟ (BU KİMDİR?)</text>\n  <text x="45" y="98" font-size="11.5" font-weight="bold" fill="#14532d">• مَنْ هٰذَا؟ → هٰذَا مُدَرِّسٌ / هُوَ صَدِيقِي</text>\n  <text x="55" y="116" font-size="10.5" fill="#334155">(Bu kimdir? → Bu bir öğretmendir / O arkadaşım.)</text>\n  <text x="45" y="144" font-size="11.5" font-weight="bold" fill="#14532d">• مَنْ هٰذِهِ؟ → هٰذِهِ طَالِبَةٌ / هِيَ مُدِيرَةٌ</text>\n  <text x="55" y="162" font-size="10.5" fill="#334155">(Bu kimdir? → Bu bir kız öğrencidir / O müdürdür.)</text>\n  <text x="45" y="192" font-size="11.5" font-weight="bold" fill="#14532d">• هَلْ هُوَ طَالِبٌ؟ → نَعَمْ، هُوَ طَالِبٌ</text>\n  <text x="55" y="210" font-size="10.5" fill="#334155">(O öğrenci mi? → Evet, o bir öğrencidir.)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">BİTİŞİK İYELİK ZAMİRLERİ (مَا اسْمُ...؟)</text>\n  <text x="380" y="98" font-size="11.5" font-weight="bold" fill="#713f12">• مَا اسْمُكَ؟ (Senin adın ne? - Erkek)</text>\n  <text x="380" y="122" font-size="11.5" font-weight="bold" fill="#713f12">• مَا اسْمُكِ؟ (Senin adın ne? - Kadın)</text>\n  <text x="380" y="146" font-size="11.5" font-weight="bold" fill="#713f12">• مَا اسْمُهُ؟ → اِسْمُهُ أَحْمَدُ (Onun adı Ahmet\'tir.)</text>\n  <text x="380" y="170" font-size="11.5" font-weight="bold" fill="#713f12">• مَا اسْمُهَا؟ → اِسْمُهَا زَيْنَبُ (Onun adı Zeynep\'tir.)</text>\n  <rect x="380" y="188" width="275" height="36" rx="6" fill="#fef08a"/>\n  <text x="517" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Ekler: ـي (benim), ـكَ (senin-e), ـكِ (senin-k), ـهُ (onun-e), ـهَا (onun-k)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SINIF İÇİ EMİRLER VE BİRİNCİ BÖLÜM BÜTÜNCÜL ÖZETİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">SINIF İÇİ EMİR FİİLLERİ (ERİL / DİŞİL)</text>\n  <text x="45" y="98" font-size="12" font-weight="bold" fill="#581c87">• تَكَلَّمْ / تَكَلَّمِي → Konuş! (Erkek / Kız)</text>\n  <text x="45" y="128" font-size="12" font-weight="bold" fill="#581c87">• اُسْكُتْ / اُسْكُتِي → Sus, sessiz ol!</text>\n  <text x="45" y="158" font-size="12" font-weight="bold" fill="#581c87">• تَعَالَ / تَعَالَيْ → Gel!</text>\n  <text x="45" y="188" font-size="12" font-weight="bold" fill="#581c87">• اِذْهَبْ / اِذْهَبِي → Git!</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" fill="#7e22ce">Muhataba (أَنْتِ) emirde fiil sonuna ي (yâ) eklenir.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">TANIŞMA SÜRECİ ADIMLARI</text>\n  <text x="380" y="98" font-size="11.5" font-weight="bold" fill="#7c2d12">1. Selamlaşma: اَلسَّلَامُ عَلَيْكُمْ / مَرْحَبًا / صَبَاحُ الْخَيْرِ</text>\n  <text x="380" y="126" font-size="11.5" font-weight="bold" fill="#7c2d12">2. İsim ve Hâl-Hatır: مَا اسْمُكَ؟ / كَيْفَ حَالُكَ؟</text>\n  <text x="380" y="154" font-size="11.5" font-weight="bold" fill="#7c2d12">3. Statü ve Tanıtma: مَنْ هٰذَا؟ هٰذَا صَدِيقِي، هُوَ طَالِبٌ</text>\n  <text x="380" y="182" font-size="11.5" font-weight="bold" fill="#7c2d12">4. Memleket ve Milliyet: مِنْ أَيْنَ أَنْتَ؟ أَنَا مِنْ تُرْكِيَا</text>\n  <text x="380" y="210" font-size="11.5" font-weight="bold" fill="#7c2d12">5. Memnuniyet ve Veda: تَشَرَّفْنَا / مَعَ السَّلَامَةِ</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
